// Written with the help of Claude
// AI Usage Note: generated by Claude; every case checked against EventImportService by running the tests.
import assert from 'node:assert/strict';
import { afterEach, beforeEach, describe, mock, test } from 'node:test';
import { Logger } from '@nestjs/common';
import type { Venue } from '../../dist/core/catalog/types/venue.js';
import type { EventProvider } from '../../dist/core/import/adapters/event-provider.js';
import type { Geocoder } from '../../dist/core/import/adapters/geocoder.js';
import type { ImportedEventsRepository } from '../../dist/core/import/repositories/imported-events.repository.js';
import { EventImportService } from '../../dist/core/import/services/event-import.service.js';
import type {
  CompleteRun,
  FetchResult,
  ImportCategory,
  ImportedEvent,
  ImportedEventRow,
  NewImportedVenue,
  NormalizeResult,
} from '../../dist/core/import/types/import.js';
import { aCategory, aVenue, CATEGORY_ID, VENUE_ID } from './fixtures/catalog.ts';

const PROVIDER_ID = 'test_provider';
/** What the test provider's list covers: from when it was read to the end of its last day. */
const COVERS = { from: '2026-10-15T09:00:00.000Z', to: '2026-11-12T21:59:59.999Z' };

/** A provider's list as `fetch` returns it; complete unless a test says otherwise. */
function aList(records: unknown[], overrides: Partial<FetchResult> = {}): FetchResult {
  return { records, complete: true, covers: COVERS, ...overrides };
}
const RUN_ID = 'f0000000-0000-4000-8000-0000000000aa';
/** The slug of aCategory(), the one category the repository knows. */
const CATEGORY_SLUG = aCategory().slug;
/** No category has it, e.g. a typo in a provider's mapping. */
const UNKNOWN_SLUG = 'concertz';

function anImportedEvent(overrides: Partial<ImportedEvent> = {}): ImportedEvent {
  return {
    externalId: 'ext-1',
    title: 'Jazz evening',
    description: 'Live quartet.',
    categorySlug: CATEGORY_SLUG,
    venue: { name: 'Caribbean Club', address: 'Kyiv', location: { lat: 50.46, lng: 30.52 } },
    startsAt: '2026-10-22T16:00:00.000Z',
    endsAt: '2026-10-22T19:00:00.000Z',
    imageUrl: 'https://images.example/jazz.jpg',
    sourceUrl: 'https://tickets.example/jazz-evening/',
    ...overrides,
  };
}

/** The row that anImportedEvent() becomes once saved, so a second run finds nothing to change. */
function theSavedEvent(overrides: Partial<ImportedEventRow> = {}): ImportedEventRow {
  return {
    id: 'e0000000-0000-4000-8000-0000000000aa',
    provider: PROVIDER_ID,
    externalId: 'ext-1',
    title: 'Jazz evening',
    description: 'Live quartet.',
    categoryId: CATEGORY_ID,
    venueId: VENUE_ID,
    startsAt: '2026-10-22T19:00:00+03:00',
    endsAt: '2026-10-22T22:00:00+03:00',
    imageUrl: 'https://images.example/jazz.jpg',
    sourceUrl: 'https://tickets.example/jazz-evening/',
    status: 'published',
    ...overrides,
  };
}

const anImportedVenue = (overrides: Partial<Venue> = {}) =>
  aVenue({ source: 'import', organizationId: null, ...overrides });

/** Every dependency of EventImportService as a mock; a test changes only what it needs. */
function makeService(raws: unknown[] = [{}], normalized: NormalizeResult[] = [{ event: anImportedEvent() }]) {
  const normalize = mock.fn((): NormalizeResult => ({ skip: { externalId: null, reason: 'unset' } }));
  normalized.forEach((result, call) => normalize.mock.mockImplementationOnce(() => result, call));
  const provider = {
    id: PROVIDER_ID,
    fetch: mock.fn((): Promise<FetchResult> => Promise.resolve(aList(raws))),
    normalize,
  };
  const repository = {
    findCategories: mock.fn((): Promise<ImportCategory[]> =>
      Promise.resolve([{ id: CATEGORY_ID, slug: CATEGORY_SLUG, isActive: true }]),
    ),
    failUnfinishedRuns: mock.fn<ImportedEventsRepository['failUnfinishedRuns']>(() => Promise.resolve()),
    lastSucceededRunStart: mock.fn((): Promise<Date | undefined> => Promise.resolve(undefined)),
    startRun: mock.fn((): Promise<string> => Promise.resolve(RUN_ID)),
    finishRun: mock.fn<ImportedEventsRepository['finishRun']>(() => Promise.resolve()),
    saveSkipped: mock.fn<ImportedEventsRepository['saveSkipped']>(() => Promise.resolve()),
    findVenues: mock.fn((): Promise<Venue[]> => Promise.resolve([])),
    updateVenueLocation: mock.fn((id: string, location: Venue['location']): Promise<Venue> =>
      Promise.resolve(anImportedVenue({ id, location })),
    ),
    createVenue: mock.fn((venue: NewImportedVenue): Promise<Venue> => Promise.resolve(anImportedVenue({ ...venue }))),
    findEvent: mock.fn((): Promise<ImportedEventRow | undefined> => Promise.resolve(undefined)),
    findOtherProvidersEvents: mock.fn((): Promise<ImportedEventRow[]> => Promise.resolve([])),
    createEvent: mock.fn((row: Omit<ImportedEventRow, 'id' | 'status'>): Promise<ImportedEventRow> =>
      Promise.resolve(theSavedEvent(row)),
    ),
    updateEvent: mock.fn<ImportedEventsRepository['updateEvent']>(() => Promise.resolve()),
    lastCompleteRun: mock.fn((): Promise<CompleteRun | undefined> => Promise.resolve(undefined)),
    cancelUnseen: mock.fn<ImportedEventsRepository['cancelUnseen']>(() => Promise.resolve(0)),
  };
  const geocoder = {
    locate: mock.fn((): Promise<Venue['location'] | undefined> => Promise.resolve({ lat: 50.45, lng: 30.52 })),
  };
  const service = new EventImportService(
    [provider as unknown as EventProvider],
    repository as unknown as ImportedEventsRepository,
    geocoder as unknown as Geocoder,
  );
  const run = () => service.importFrom(provider as unknown as EventProvider);
  return { service, run, provider, repository, geocoder };
}

// FR-008, FLEX-003
describe('EventImportService.importFrom', () => {
  test('saves a new event with the provider and its id for the record', async () => {
    const { run, repository } = makeService();

    const report = await run();

    assert.deepEqual(repository.createEvent.mock.calls[0]?.arguments[0], {
      title: 'Jazz evening',
      description: 'Live quartet.',
      categoryId: CATEGORY_ID,
      venueId: VENUE_ID,
      startsAt: '2026-10-22T16:00:00.000Z',
      endsAt: '2026-10-22T19:00:00.000Z',
      imageUrl: 'https://images.example/jazz.jpg',
      sourceUrl: 'https://tickets.example/jazz-evening/',
      provider: PROVIDER_ID,
      externalId: 'ext-1',
    });
    assert.deepEqual(report, {
      provider: PROVIDER_ID,
      complete: true,
      fetched: 1,
      created: 1,
      updated: 0,
      unchanged: 0,
      cancelled: 0,
      republished: 0,
      skipped: [],
    });
  });

  test('creates the venue when it is not known yet', async () => {
    const { run, repository } = makeService();

    await run();

    assert.deepEqual(repository.createVenue.mock.calls[0]?.arguments, [anImportedEvent().venue]);
  });

  test('reuses a venue an earlier import created', async () => {
    const { run, repository } = makeService();
    const { name, address, location } = anImportedEvent().venue;
    repository.findVenues.mock.mockImplementation(() =>
      Promise.resolve([anImportedVenue({ id: 'known-venue', name, address, location: location ?? undefined })]),
    );

    await run();

    assert.equal(repository.createVenue.mock.callCount(), 0);
    assert.equal(repository.createEvent.mock.calls[0]?.arguments[0].venueId, 'known-venue');
  });

  test('looks the event up by provider and external id, so an organization event is never touched', async () => {
    const { run, repository } = makeService();

    await run();

    assert.deepEqual(repository.findEvent.mock.calls[0]?.arguments, [PROVIDER_ID, 'ext-1']);
  });

  test('leaves an event the provider has not changed', async () => {
    const { run, repository } = makeService();
    repository.findEvent.mock.mockImplementation(() => Promise.resolve(theSavedEvent()));

    const report = await run();

    assert.equal(repository.createEvent.mock.callCount(), 0);
    assert.equal(repository.updateEvent.mock.callCount(), 0);
    assert.deepEqual([report.created, report.updated, report.unchanged], [0, 0, 1]);
  });

  test('updates an event whose title the provider changed', async () => {
    const { run, repository } = makeService([{}], [{ event: anImportedEvent({ title: 'Jazz evening, new date' }) }]);
    repository.findEvent.mock.mockImplementation(() => Promise.resolve(theSavedEvent()));

    const report = await run();

    const [id, changes] = repository.updateEvent.mock.calls[0]?.arguments ?? [];
    assert.equal(id, theSavedEvent().id);
    assert.equal(changes?.title, 'Jazz evening, new date');
    assert.deepEqual([report.created, report.updated, report.unchanged], [0, 1, 0]);
  });

  test('saves the event under the id of the category with its slug', async () => {
    const { run, repository } = makeService();

    await run();

    assert.equal(repository.createEvent.mock.calls[0]?.arguments[0].categoryId, CATEGORY_ID);
  });

  test('skips a record whose category slug is unknown, names the slug and saves nothing for it', async () => {
    const { run, repository } = makeService([{}], [{ event: anImportedEvent({ categorySlug: UNKNOWN_SLUG }) }]);

    const report = await run();

    assert.deepEqual(report.skipped, [{ externalId: 'ext-1', reason: 'Unknown category "concertz"' }]);
    assert.equal(repository.createEvent.mock.callCount(), 0);
    assert.equal(repository.createVenue.mock.callCount(), 0);
  });

  test('skips a record whose category an admin deactivated', async () => {
    const { run, repository } = makeService();
    repository.findCategories.mock.mockImplementation(() =>
      Promise.resolve([{ id: CATEGORY_ID, slug: CATEGORY_SLUG, isActive: false }]),
    );

    const report = await run();

    assert.deepEqual(report.skipped, [{ externalId: 'ext-1', reason: `Inactive category "${CATEGORY_SLUG}"` }]);
    assert.equal(repository.createEvent.mock.callCount(), 0);
  });

  const badTimes = [
    { title: 'an event that ends before it starts', endsAt: '2026-10-22T15:00:00.000Z' },
    { title: 'an event that ends when it starts', endsAt: '2026-10-22T16:00:00.000Z' },
  ];
  for (const { title, endsAt } of badTimes) {
    test(`skips ${title}`, async () => {
      const { run, repository } = makeService([{}], [{ event: anImportedEvent({ endsAt }) }]);

      const report = await run();

      assert.equal(report.skipped[0]?.reason, 'The event does not end after it starts');
      assert.equal(repository.createEvent.mock.callCount(), 0);
    });
  }

  test('reports a record the adapter skipped and still imports the others', async () => {
    const { run, repository } = makeService(
      [{}, {}],
      [
        { skip: { externalId: 'bad-1', reason: 'Invalid record: title' } },
        { event: anImportedEvent({ externalId: 'ext-2' }) },
      ],
    );

    const report = await run();

    assert.deepEqual(report.skipped, [{ externalId: 'bad-1', reason: 'Invalid record: title' }]);
    assert.equal(report.created, 1);
    assert.equal(repository.createEvent.mock.calls[0]?.arguments[0].externalId, 'ext-2');
  });

  test('reports a skipped record without an id and logs it as a record without id', async () => {
    const skip = { externalId: null, reason: 'Invalid record: id' };
    const { run } = makeService([{}], [{ skip }]);
    const warn = mock.method(Logger.prototype, 'warn', () => {});

    const report = await run();

    assert.deepEqual(report.skipped, [skip]);
    const [message] = warn.mock.calls[0]?.arguments as [string];
    assert.match(message, /a record without id/);
    warn.mock.restore();
  });

  test('reports whether the provider gave its full list, and still imports a partial one', async () => {
    const { run, provider } = makeService();
    provider.fetch.mock.mockImplementation(() => Promise.resolve(aList([{}], { complete: false })));
    const log = mock.method(Logger.prototype, 'log', () => {});

    const report = await run();

    assert.equal(report.complete, false);
    assert.equal(report.created, 1);
    assert.match(String(log.mock.calls.at(-1)?.arguments[0]), /; not the full list$/);
    log.mock.restore();
  });

  test('imports nothing from an empty feed, and takes it as not complete', async () => {
    const { run } = makeService([], []);

    assert.deepEqual(await run(), {
      provider: PROVIDER_ID,
      complete: false,
      fetched: 0,
      created: 0,
      updated: 0,
      unchanged: 0,
      cancelled: 0,
      republished: 0,
      skipped: [],
    });
  });

  test('lets a failing fetch stop the run, so the catalog keeps the last imported events (FR-014)', async () => {
    const { run, provider, repository } = makeService();
    provider.fetch.mock.mockImplementation(() => Promise.reject(new Error('Karabas is down')));

    await assert.rejects(run(), /Karabas is down/);

    assert.equal(repository.createEvent.mock.callCount(), 0);
    assert.deepEqual(repository.finishRun.mock.calls[0]?.arguments, [RUN_ID, 'failed']);
  });

  test('records the run under the provider and finishes it as succeeded', async () => {
    const { run, repository } = makeService();

    await run();

    assert.deepEqual(repository.startRun.mock.calls[0]?.arguments, [PROVIDER_ID]);
    assert.deepEqual(repository.finishRun.mock.calls[0]?.arguments.slice(0, 2), [RUN_ID, 'succeeded']);
    assert.equal(repository.finishRun.mock.callCount(), 1);
  });

  test('keeps each skipped record as received, with its reason, under the run', async () => {
    const unusable = { id: 'bad-1', title: '' };
    const unknownCategory = { id: 'ext-1', genre: 'Comedy' };
    const { run, repository } = makeService(
      [unusable, unknownCategory],
      [
        { skip: { externalId: 'bad-1', reason: 'Invalid record: title' } },
        { event: anImportedEvent({ categorySlug: UNKNOWN_SLUG }) },
      ],
    );

    await run();

    assert.deepEqual(
      repository.saveSkipped.mock.calls.map((call) => call.arguments),
      [
        [RUN_ID, unusable, 'Invalid record: title'],
        [RUN_ID, unknownCategory, 'Unknown category "concertz"'],
      ],
    );
  });
});

describe('EventImportService.importFrom, with a venue without coordinates', () => {
  const withoutCoordinates = anImportedEvent({
    venue: { name: 'Docker-G pub', address: 'вул. Ігорівська, 13/5, Київ', location: null },
  });

  test('reuses the venue an earlier import saved with that name and address, without asking the geocoder', async () => {
    const { run, repository, geocoder } = makeService([{}], [{ event: withoutCoordinates }]);
    repository.findVenues.mock.mockImplementation(() =>
      Promise.resolve([
        anImportedVenue({ id: 'known-venue', name: 'Docker-G pub', address: 'вул. Ігорівська, 13/5, Київ' }),
      ]),
    );

    await run();

    assert.equal(geocoder.locate.mock.callCount(), 0);
    assert.equal(repository.createEvent.mock.calls[0]?.arguments[0].venueId, 'known-venue');
  });

  test('saves a new venue with the coordinates the geocoder found', async () => {
    const { run, repository, geocoder } = makeService([{}], [{ event: withoutCoordinates }]);

    await run();

    assert.deepEqual(geocoder.locate.mock.calls[0]?.arguments, [withoutCoordinates.venue]);
    assert.deepEqual(repository.createVenue.mock.calls[0]?.arguments, [
      { ...withoutCoordinates.venue, location: { lat: 50.45, lng: 30.52 } },
    ]);
  });

  test('skips the event when the geocoder finds nothing, and asks about the venue once per run', async () => {
    const { run, repository, geocoder } = makeService(
      [{}, {}],
      [{ event: withoutCoordinates }, { event: { ...withoutCoordinates, externalId: 'ext-2' } }],
    );
    geocoder.locate.mock.mockImplementation(() => Promise.resolve(undefined));

    const report = await run();

    assert.deepEqual(report.skipped, [
      { externalId: 'ext-1', reason: 'The geocoder found no coordinates for the venue' },
      { externalId: 'ext-2', reason: 'The geocoder found no coordinates for the venue' },
    ]);
    assert.equal(geocoder.locate.mock.callCount(), 1);
    assert.equal(repository.createVenue.mock.callCount(), 0);
    assert.equal(repository.createEvent.mock.callCount(), 0);
  });

  test('skips the event when the geocoder fails, and imports the rest', async () => {
    const { run, geocoder } = makeService(
      [{}, {}],
      [{ event: withoutCoordinates }, { event: anImportedEvent({ externalId: 'ext-2' }) }],
    );
    geocoder.locate.mock.mockImplementation(() => Promise.reject(new Error('Nominatim answered 503')));

    const report = await run();

    assert.deepEqual(report.skipped, [{ externalId: 'ext-1', reason: 'The geocoder failed: Nominatim answered 503' }]);
    assert.equal(report.created, 1);
  });
});

// ADR-006, decision 7: the venues of these tests are the pairs of the live runs of 2026-11-07 and 2026-11-08.
describe('EventImportService.importFrom, venue reuse', () => {
  const geocoded = { lat: 50.436352, lng: 30.519508 };
  const saved = (id: string, name: string, address: string, location = geocoded) =>
    anImportedVenue({ id, name, address, location });
  const arriving = (name: string, address: string, location: Venue['location'] | null = null) =>
    anImportedEvent({ venue: { name, address, location } });

  async function venueOf(savedVenues: Venue[], event: ImportedEvent) {
    const { run, repository, geocoder } = makeService([{}], [{ event }]);
    repository.findVenues.mock.mockImplementation(() => Promise.resolve(savedVenues));
    await run();
    return { venueId: repository.createEvent.mock.calls[0]?.arguments[0].venueId, repository, geocoder };
  }

  const joined: [string, string, string, string][] = [
    ['Будинок Кіно', 'вулиця Саксаганського, 6, Київ', '«Будинок Кіно»', 'вул. Саксаганського, 6, Київ'],
    ['Будинок Кіно', 'вулиця Саксаганського, 6, Київ', 'Будинок кіно', 'вул. Саксаганського, 6, Київ'],
    ['Хора', 'Бульварно-Кудрявська, 22, Київ', 'Хора', 'вул. Бульварно-Кудрявська, 22, Київ'],
    [
      "Pepper's Club",
      'вулиця Князів Острозьких, 8, Київ',
      'Music Pub "Pepper\'s Club"',
      'вул Князів Острозьких, 8, Київ',
    ],
    ['CARIBBEAN club', 'вул. С. Петлюри, 4, Київ', 'Caribbean Club', 'вул. С. Петлюри, 4, Київ'],
    [
      'Театр «Особистості»',
      'вул. Січових Стрільців, 1-5, Центральний Будинок Художника, Київ',
      '"Особистості"',
      'вул. Січових Стрільців, 1-5, Центральний Будинок Художника, Київ',
    ],
    ['Будинок архітектора', 'вул. Бориса Грінченка, 7, Київ', 'Архітектора', 'вул. Бориса Грінченка, 7, Київ'],
    ['Палац «Україна»', 'вул. В. Васильківська, 103, Київ', 'Палац Україна', 'вул. В. Васильківська, 103, Київ'],
    [
      'Національний палац мистецтв «Україна»',
      'вул. В. Васильківська, 103, Київ',
      'Палац Україна',
      'вул. В. Васильківська, 103, Київ',
    ],
    ['МЦКМ', 'Алея Героїв Небесної Сотні, 1, Київ', 'МЦКМ (Жовтневий палац)', 'Алея Героїв Небесної Сотні, 1, Київ'],
    [
      'Місце проведення: МЦКМ',
      'Алея Героїв Небесної Сотні, 1, Київ',
      'МЦКМ (Жовтневий палац)',
      'Алея Героїв Небесної Сотні, 1, Київ',
    ],
    ['Stereo Plaza', 'Лобановського пр-т, 119, Київ', 'Stereo Plaza. Мала зала', 'Лобановського пр-т, 119'],
    [
      'Будинок Офіцерів',
      'вул. Грушевського, 30/1, Київ',
      'Центральний будинок офіцерів Збройних Сил України',
      'вул. М. Грушевського, 30/1, Київ',
    ],
    [
      'Театр "Браво"',
      'вул. Олеся Гончара, 79, Київ',
      'Київський драматичний театр Браво',
      'вул. Олеся Гончара, 79, Київ',
    ],
  ];
  for (const [savedName, savedAddress, name, address] of joined) {
    test(`reuses "${savedName}" for "${name}"`, async () => {
      const { venueId, repository } = await venueOf([saved('saved', savedName, savedAddress)], arriving(name, address));

      assert.equal(venueId, 'saved');
      assert.equal(repository.createVenue.mock.callCount(), 0);
    });
  }

  const apart: [string, string, string, string][] = [
    ['Реверб', 'Нижньоюрківська, 31, Київ', 'Otel’', 'вул. Нижньоюрківська 31, Київ'],
    ['Закапелок', 'вулиця Верхній Вал, 62, Київ', 'Продюсерський центр Ізмайлової', 'вул. Верхній Вал, 66а, Київ'],
    ['Закапелок', 'вул. Верхній Вал, 66а, Київ', 'Продюсерський центр Ізмайлової', 'вул. Верхній Вал, 66а, Київ'],
    ['Будинок Кіно', 'вулиця Саксаганського, 6, Київ', 'Будинок вчених', 'вул. Саксаганського, 6, Київ'],
  ];
  for (const [savedName, savedAddress, name, address] of apart) {
    test(`keeps "${savedName}" and "${name}" apart, whatever the address`, async () => {
      const { venueId, repository } = await venueOf([saved('saved', savedName, savedAddress)], arriving(name, address));

      assert.notEqual(venueId, 'saved');
      assert.equal(repository.createVenue.mock.callCount(), 1);
    });
  }

  test('reuses a similar name at another address never', async () => {
    const { venueId } = await venueOf(
      [saved('saved', 'Будинок Кіно', 'вулиця Саксаганського, 6, Київ')],
      arriving('Будинок Кіно', 'вул. Саксаганського, 8, Київ'),
    );

    assert.notEqual(venueId, 'saved');
  });

  test('finds a venue saved with the city twice', async () => {
    const { venueId } = await venueOf(
      [saved('saved-before', 'Будинок Кіно', 'вулиця Саксаганського, 6, Київ, Київ')],
      arriving('Будинок Кіно', 'вулиця Саксаганського, 6, Київ', { lat: 50.43626, lng: 30.5195 }),
    );

    assert.equal(venueId, 'saved-before');
  });

  test('matches an address without a house number only with the same name', async () => {
    const kpi = 'Палац культури КПІ ім. Ігоря Сікорського';
    const same = await venueOf([saved('saved', kpi, 'Київ')], arriving(kpi, 'Київ'));
    const other = await venueOf([saved('saved', kpi, 'Київ')], arriving('Палац культури', 'Київ'));

    assert.equal(same.venueId, 'saved');
    assert.notEqual(other.venueId, 'saved');
  });

  test('takes the oldest of the saved duplicates, so their events end up at one venue', async () => {
    const { venueId } = await venueOf(
      [
        saved('oldest', 'CARIBBEAN club', 'вул. С. Петлюри, 4, Київ'),
        saved('newer', 'Caribbean Club', 'вул. С. Петлюри, 4, Київ'),
      ],
      arriving('Caribbean Club', 'вул. С. Петлюри, 4, Київ'),
    );

    assert.equal(venueId, 'oldest');
  });

  test('moves an event saved at a duplicate to the reused venue', async () => {
    const event = arriving('Caribbean Club', 'вул. С. Петлюри, 4, Київ');
    const { run, repository } = makeService([{}], [{ event }]);
    repository.findVenues.mock.mockImplementation(() =>
      Promise.resolve([
        saved('oldest', 'CARIBBEAN club', 'вул. С. Петлюри, 4, Київ'),
        saved('newer', 'Caribbean Club', 'вул. С. Петлюри, 4, Київ'),
      ]),
    );
    repository.findEvent.mock.mockImplementation(() => Promise.resolve(theSavedEvent({ venueId: 'newer' })));

    const report = await run();

    assert.equal(repository.updateEvent.mock.calls[0]?.arguments[1].venueId, 'oldest');
    assert.equal(report.updated, 1);
  });

  test('gives the saved venue the provider coordinates, without asking the geocoder', async () => {
    const artWizard = { lat: 50.4362609434499, lng: 30.5195041135087 };
    const { venueId, repository, geocoder } = await venueOf(
      [saved('karabas-venue', 'Будинок кіно', 'вул. Саксаганського, 6, Київ')],
      arriving('Будинок Кіно', 'вулиця Саксаганського, 6, Київ', artWizard),
    );

    assert.equal(venueId, 'karabas-venue');
    assert.deepEqual(repository.updateVenueLocation.mock.calls[0]?.arguments, ['karabas-venue', artWizard]);
    assert.equal(geocoder.locate.mock.callCount(), 0);
  });

  test('leaves the coordinates alone when they are the same at the precision the database keeps', async () => {
    const { repository } = await venueOf(
      [saved('saved', 'Будинок Кіно', 'вулиця Саксаганського, 6, Київ', { lat: 50.436261, lng: 30.519504 })],
      arriving('Будинок Кіно', 'вулиця Саксаганського, 6, Київ', { lat: 50.4362609434499, lng: 30.5195041135087 }),
    );

    assert.equal(repository.updateVenueLocation.mock.callCount(), 0);
  });

  test('keeps the saved coordinates when the provider puts the venue outside Kyiv', async () => {
    // ArtWizard's "Печерськ Палац" on 2026-11-08, about 300 km west of Kyiv.
    const { venueId, repository } = await venueOf(
      [
        saved(
          'karabas-venue',
          'Культурний центр "Печерськ Палац"',
          'вул. Князів Острозьких 3 (метро Арсенальна), Київ',
        ),
      ],
      arriving('Печерськ Палац', 'вул.Князів Острозьких,3, Київ', { lat: 50.328466, lng: 26.519548 }),
    );

    assert.equal(venueId, 'karabas-venue');
    assert.equal(repository.updateVenueLocation.mock.callCount(), 0);
  });

  test('never gives a venue without coordinates a saved one placed outside Kyiv', async () => {
    const { venueId, geocoder } = await venueOf(
      [saved('outside', 'Печерськ Палац', 'вул.Князів Острозьких,3, Київ', { lat: 50.328466, lng: 26.519548 })],
      arriving('Культурний центр "Печерськ Палац"', 'вул. Князів Острозьких 3 (метро Арсенальна), Київ'),
    );

    assert.notEqual(venueId, 'outside');
    assert.equal(geocoder.locate.mock.callCount(), 1);
  });

  test('reuses a venue placed outside Kyiv for the provider that placed it there, so it is not saved again', async () => {
    const outside = { lat: 50.328466, lng: 26.519548 };
    const { venueId, repository } = await venueOf(
      [saved('outside', 'Печерськ Палац', 'вул.Князів Острозьких,3, Київ', outside)],
      arriving('Печерськ Палац', 'вул.Князів Острозьких,3, Київ', { lat: 50.328465652605175, lng: 26.519547728835764 }),
    );

    assert.equal(venueId, 'outside');
    assert.equal(repository.createVenue.mock.callCount(), 0);
  });

  test('prefers a fitting venue in Kyiv to an older one placed outside it', async () => {
    const { venueId } = await venueOf(
      [
        saved('outside', 'Печерськ Палац', 'вул.Князів Острозьких,3, Київ', { lat: 50.328466, lng: 26.519548 }),
        saved('in-kyiv', 'Культурний центр "Печерськ Палац"', 'вул. Князів Острозьких 3 (метро Арсенальна), Київ'),
      ],
      arriving('Печерськ Палац', 'вул.Князів Острозьких,3, Київ', { lat: 50.328466, lng: 26.519548 }),
    );

    assert.equal(venueId, 'in-kyiv');
  });

  test('reuses a venue whose name is only generic words for the same name', async () => {
    // On 2026-11-08 every event of "Малий театр" got a venue of its own before this was fixed.
    const { venueId, repository } = await venueOf(
      [saved('saved', 'Малий театр', 'вул. Олеся Гончара, 33, Київ')],
      arriving('Малий театр', 'вул. Олеся Гончара, 33, Київ'),
    );

    assert.equal(venueId, 'saved');
    assert.equal(repository.createVenue.mock.callCount(), 0);
  });

  test('reuses a venue saved earlier in the same run', async () => {
    const { run, repository } = makeService(
      [{}, {}],
      [
        { event: arriving('CARIBBEAN club', 'вул. С. Петлюри, 4, Київ', geocoded) },
        { event: { ...arriving('Caribbean Club', 'вул. С. Петлюри, 4, Київ'), externalId: 'ext-2' } },
      ],
    );

    await run();

    assert.equal(repository.createVenue.mock.callCount(), 1);
  });
});

