// ADR-006: an event gone from a provider's complete list is no longer served as published.
describe('EventImportService.importFrom, removed and cancelled events', () => {
  const withoutCoordinates = (externalId: string) =>
    anImportedEvent({ externalId, venue: { name: 'Docker-G pub', address: 'Ігорівська, 13/5', location: null } });
  let warn: ReturnType<typeof mock.method>;
  beforeEach(() => {
    warn = mock.method(Logger.prototype, 'warn', () => {});
  });
  afterEach(() => warn.mock.restore());
  const warnings = () => warn.mock.calls.map((call) => String(call.arguments[0]));

  test('cancels, after a complete list, the provider’s events it no longer lists, within what the list covers', async () => {
    const { run, repository } = makeService(
      [{}, {}],
      [{ event: anImportedEvent() }, { event: anImportedEvent({ externalId: 'ext-2' }) }],
    );
    repository.cancelUnseen.mock.mockImplementation(() => Promise.resolve(3));

    const report = await run();

    assert.deepEqual(repository.cancelUnseen.mock.calls[0]?.arguments, [PROVIDER_ID, ['ext-1', 'ext-2'], COVERS]);
    assert.equal(report.cancelled, 3);
    assert.equal(report.complete, true);
  });

  test('counts an event skipped only because the geocoder found nothing or failed as seen', async () => {
    const { run, repository, geocoder } = makeService(
      [{}, {}, {}],
      [
        { event: withoutCoordinates('not-found') },
        {
          event: { ...withoutCoordinates('geocoder-down'), venue: { name: 'Other', address: 'Other', location: null } },
        },
        { event: anImportedEvent() },
      ],
    );
    geocoder.locate.mock.mockImplementationOnce(() => Promise.resolve(undefined), 0);
    geocoder.locate.mock.mockImplementationOnce(() => Promise.reject(new Error('Nominatim answered 503')), 1);

    const report = await run();

    assert.equal(report.skipped.length, 2);
    assert.deepEqual(repository.cancelUnseen.mock.calls[0]?.arguments[1], ['not-found', 'geocoder-down', 'ext-1']);
  });

  test('does not count an event skipped for any other reason as seen, so a stored one is cancelled', async () => {
    const { run, repository } = makeService(
      [{}, {}, {}],
      [
        { skip: { externalId: 'no-start-time', reason: 'No start time (00:00 on ArtWizard)' } },
        { event: anImportedEvent({ externalId: 'comedy', categorySlug: 'comedy' }) },
        { event: anImportedEvent() },
      ],
    );

    await run();

    assert.deepEqual(repository.cancelUnseen.mock.calls[0]?.arguments[1], ['ext-1']);
  });

  test('cancels nothing after a list that is not complete, and records the run as not complete', async () => {
    const { run, provider, repository } = makeService();
    provider.fetch.mock.mockImplementation(() => Promise.resolve(aList([{}], { complete: false })));

    const report = await run();

    assert.equal(repository.cancelUnseen.mock.callCount(), 0);
    assert.equal(report.cancelled, 0);
    assert.deepEqual(repository.finishRun.mock.calls[0]?.arguments, [
      RUN_ID,
      'succeeded',
      { complete: false, seen: 1, parts: undefined },
    ]);
    assert.deepEqual(warnings(), [`${PROVIDER_ID}: cancelling nothing: the list is not complete`]);
  });

  test('cancels nothing after a failed run', async () => {
    const { run, provider, repository } = makeService();
    provider.fetch.mock.mockImplementation(() => Promise.reject(new Error('Karabas is down')));

    await assert.rejects(run(), /Karabas is down/);

    assert.equal(repository.cancelUnseen.mock.callCount(), 0);
  });

  test('cancels nothing when the list saw under half the records of the last complete one', async () => {
    const { run, repository } = makeService([{}], [{ event: anImportedEvent() }]);
    repository.lastCompleteRun.mock.mockImplementation(() => Promise.resolve({ seen: 3, parts: {} }));

    const report = await run();

    assert.equal(repository.cancelUnseen.mock.callCount(), 0);
    assert.equal(report.complete, false);
    assert.deepEqual(warnings(), [
      `${PROVIDER_ID}: cancelling nothing: it saw 1 records, under half of the 3 of the last complete list`,
    ]);
  });

  test('still cancels when the list saw half the records of the last complete one', async () => {
    const { run, repository } = makeService(
      [{}, {}],
      [{ event: anImportedEvent() }, { event: anImportedEvent({ externalId: 'ext-2' }) }],
    );
    repository.lastCompleteRun.mock.mockImplementation(() => Promise.resolve({ seen: 4, parts: {} }));

    await run();

    assert.equal(repository.cancelUnseen.mock.callCount(), 1);
  });

  test('cancels nothing when a part that listed records in the last complete list lists none now', async () => {
    const { run, provider, repository } = makeService();
    provider.fetch.mock.mockImplementation(() =>
      Promise.resolve(aList([{}], { parts: { '/concerts/': 1, '/festivals/': 0 } })),
    );
    repository.lastCompleteRun.mock.mockImplementation(() =>
      Promise.resolve({ seen: 1, parts: { '/concerts/': 1, '/festivals/': 4 } }),
    );

    const report = await run();

    assert.equal(repository.cancelUnseen.mock.callCount(), 0);
    assert.equal(report.complete, false);
    assert.deepEqual(warnings(), [
      `${PROVIDER_ID}: cancelling nothing: /festivals/ listed records in the last complete list and none now`,
    ]);
  });

  test('takes a part that listed nothing in the last complete list and nothing now as whole', async () => {
    const { run, provider, repository } = makeService();
    provider.fetch.mock.mockImplementation(() =>
      Promise.resolve(aList([{}], { parts: { '/concerts/': 1, '/festivals/': 0 } })),
    );
    repository.lastCompleteRun.mock.mockImplementation(() =>
      Promise.resolve({ seen: 1, parts: { '/concerts/': 1, '/festivals/': 0 } }),
    );

    await run();

    assert.equal(repository.cancelUnseen.mock.callCount(), 1);
  });

  test('cancels nothing after a complete list that saw no records, even without an earlier complete list', async () => {
    const { run, repository } = makeService([{}], [{ event: anImportedEvent({ categorySlug: 'comedy' }) }]);

    const report = await run();

    assert.equal(repository.cancelUnseen.mock.callCount(), 0);
    assert.equal(report.complete, false);
    assert.deepEqual(warnings(), [
      `${PROVIDER_ID}: skipped ext-1: Unknown category "comedy"`,
      `${PROVIDER_ID}: cancelling nothing: it saw no records`,
    ]);
  });

  test('publishes again a cancelled event the provider lists again', async () => {
    const { run, repository } = makeService();
    repository.findEvent.mock.mockImplementation(() => Promise.resolve(theSavedEvent({ status: 'cancelled' })));

    const report = await run();

    assert.deepEqual(repository.updateEvent.mock.calls[0]?.arguments[0], theSavedEvent().id);
    assert.deepEqual([report.updated, report.republished, report.unchanged], [1, 1, 0]);
  });

  test('records what a complete run saw, for the checks of the next one', async () => {
    const { run, provider, repository } = makeService();
    provider.fetch.mock.mockImplementation(() => Promise.resolve(aList([{}], { parts: { '/concerts/': 1 } })));

    await run();

    assert.deepEqual(repository.lastCompleteRun.mock.calls[0]?.arguments, [PROVIDER_ID]);
    assert.deepEqual(repository.finishRun.mock.calls[0]?.arguments, [
      RUN_ID,
      'succeeded',
      { complete: true, seen: 1, parts: { '/concerts/': 1 } },
    ]);
  });
});

// FR-014, REL-003: the repository stub throws where the database would.
describe('EventImportService.importFrom, when the database fails', () => {
  const databaseDown = () => Promise.reject(new Error('Connection terminated'));

  test('marks the provider’s unfinished runs as failed before it starts a new run', async () => {
    const { run, repository } = makeService();
    const order: string[] = [];
    repository.failUnfinishedRuns.mock.mockImplementation(() => (order.push('failUnfinishedRuns'), Promise.resolve()));
    repository.startRun.mock.mockImplementation(() => (order.push('startRun'), Promise.resolve(RUN_ID)));

    await run();

    assert.deepEqual(repository.failUnfinishedRuns.mock.calls[0]?.arguments, [PROVIDER_ID]);
    assert.deepEqual(order, ['failUnfinishedRuns', 'startRun']);
  });

  test('rethrows the original error when recording the failed run fails too, and logs the second error', async () => {
    const { run, provider, repository } = makeService();
    provider.fetch.mock.mockImplementation(() => Promise.reject(new Error('Karabas is down')));
    repository.finishRun.mock.mockImplementation(databaseDown);
    const error = mock.method(Logger.prototype, 'error', () => {});

    await assert.rejects(run(), { message: 'Karabas is down' });

    assert.deepEqual(repository.finishRun.mock.calls[0]?.arguments, [RUN_ID, 'failed']);
    const [message] = error.mock.calls[0]?.arguments as [string];
    assert.equal(message, `${PROVIDER_ID}: could not record run ${RUN_ID} as failed: Connection terminated`);
    error.mock.restore();
  });

  test('rethrows a database error in the middle of the run after recording the run as failed', async () => {
    const { run, repository } = makeService();
    repository.createEvent.mock.mockImplementation(databaseDown);

    await assert.rejects(run(), { message: 'Connection terminated' });

    assert.deepEqual(
      repository.finishRun.mock.calls.map((call) => call.arguments),
      [[RUN_ID, 'failed']],
    );
  });

  test('rethrows the error of recording a succeeded run, and does not record it as failed instead', async () => {
    const { run, repository } = makeService();
    repository.finishRun.mock.mockImplementation(databaseDown);

    await assert.rejects(run(), { message: 'Connection terminated' });

    assert.deepEqual(
      repository.finishRun.mock.calls.map((call) => call.arguments),
      [[RUN_ID, 'succeeded', { complete: true, seen: 1, parts: undefined }]],
    );
  });

  type Repository = ReturnType<typeof makeService>['repository'];
  const beforeTheRun: [string, (repository: Repository) => void][] = [
    ['failUnfinishedRuns', (repository) => repository.failUnfinishedRuns.mock.mockImplementation(databaseDown)],
    ['lastSucceededRunStart', (repository) => repository.lastSucceededRunStart.mock.mockImplementation(databaseDown)],
    ['startRun', (repository) => repository.startRun.mock.mockImplementation(databaseDown)],
  ];
  for (const [method, fail] of beforeTheRun) {
    test(`lets an error of ${method} propagate, without fetching or recording anything`, async () => {
      const { run, provider, repository } = makeService();
      fail(repository);

      await assert.rejects(run(), { message: 'Connection terminated' });

      assert.equal(provider.fetch.mock.callCount(), 0);
      assert.equal(repository.finishRun.mock.callCount(), 0);
    });
  }
});

describe('EventImportService.run', () => {
  test('reports a provider whose run the database could not start, and still imports the next one', async () => {
    const { provider, repository, geocoder } = makeService();
    const second = {
      id: 'up',
      fetch: () => Promise.resolve(aList([{}])),
      normalize: () => ({ event: anImportedEvent() }),
    };
    const service = new EventImportService(
      [provider, second] as unknown as EventProvider[],
      repository as unknown as ImportedEventsRepository,
      geocoder as unknown as Geocoder,
    );
    repository.startRun.mock.mockImplementationOnce(() => Promise.reject(new Error('Connection terminated')), 0);
    const error = mock.method(Logger.prototype, 'error', () => {});

    const summary = await service.run();

    assert.deepEqual(summary.failed, [{ provider: PROVIDER_ID, error: 'Connection terminated' }]);
    assert.deepEqual(
      summary.reports.map((report) => [report.provider, report.created]),
      [['up', 1]],
    );
    error.mock.restore();
  });

  test('imports from every provider and reports a failed one without stopping the others', async () => {
    const { repository, geocoder } = makeService();
    const failing = { id: 'down', fetch: () => Promise.reject(new Error('Karabas is down')), normalize: () => null };
    const working = {
      id: 'up',
      fetch: () => Promise.resolve(aList([{}])),
      normalize: () => ({ event: anImportedEvent() }),
    };
    const service = new EventImportService(
      [failing, working] as unknown as EventProvider[],
      repository as unknown as ImportedEventsRepository,
      geocoder as unknown as Geocoder,
    );
    const error = mock.method(Logger.prototype, 'error', () => {});

    const summary = await service.run();

    assert.deepEqual(summary.failed, [{ provider: 'down', error: 'Karabas is down' }]);
    assert.deepEqual(
      summary.reports.map((report) => [report.provider, report.created]),
      [['up', 1]],
    );
    assert.deepEqual(
      repository.finishRun.mock.calls.map((call) => call.arguments[1]),
      ['failed', 'succeeded'],
    );
    error.mock.restore();
  });
});

// ADR-006, decision 8: an event both providers list is saved once.
describe('EventImportService.importFrom, duplicates across providers', () => {
  const KARABAS_EVENT_ID = 'e0000000-0000-4000-8000-0000000000bb';
  /** Karabas' event as saved by its earlier run, at the same venue and time. */
  const karabasEvent = (title: string) =>
    theSavedEvent({
      id: KARABAS_EVENT_ID,
      provider: 'karabas',
      externalId: 'bridgerton-rozkishnij-vechir',
      title,
      startsAt: '2026-10-22T16:00:00.000Z',
    });
  const artWizardRecord = () => ({
    event: anImportedEvent({
      externalId: 'bridgerton-candlelight',
      title: 'Bridgerton: Розкішний вечір музики при свічках',
    }),
  });

  test('does not save an event another provider’s event at the same venue and time already shows', async () => {
    const { run, repository } = makeService([{ slug: 'bridgerton-candlelight' }], [artWizardRecord()]);
    repository.findOtherProvidersEvents.mock.mockImplementation(() =>
      Promise.resolve([karabasEvent('Bridgerton. Розкішний вечір музики при свічках')]),
    );
    mock.method(Logger.prototype, 'warn', () => {});

    const report = await run();

    assert.deepEqual(repository.findOtherProvidersEvents.mock.calls[0]?.arguments, [
      PROVIDER_ID,
      VENUE_ID,
      '2026-10-22T16:00:00.000Z',
    ]);
    assert.equal(repository.createEvent.mock.callCount(), 0);
    const reason = `Duplicate of karabas event ${KARABAS_EVENT_ID}`;
    assert.deepEqual(report.skipped, [{ externalId: 'bridgerton-candlelight', reason }]);
    assert.deepEqual(repository.saveSkipped.mock.calls[0]?.arguments, [
      RUN_ID,
      { slug: 'bridgerton-candlelight' },
      reason,
    ]);
    mock.restoreAll();
  });

  test('counts a duplicate as seen, so the provider’s other events are cancelled as usual and the run is complete', async () => {
    const { run, repository } = makeService([{}], [artWizardRecord()]);
    repository.findOtherProvidersEvents.mock.mockImplementation(() =>
      Promise.resolve([karabasEvent('Bridgerton. Розкішний вечір музики при свічках')]),
    );
    mock.method(Logger.prototype, 'warn', () => {});

    const report = await run();

    assert.equal(report.complete, true);
    assert.deepEqual(repository.cancelUnseen.mock.calls[0]?.arguments, [
      PROVIDER_ID,
      ['bridgerton-candlelight'],
      COVERS,
    ]);
    assert.deepEqual(repository.finishRun.mock.calls[0]?.arguments, [
      RUN_ID,
      'succeeded',
      { complete: true, seen: 1, parts: undefined },
    ]);
    mock.restoreAll();
  });

  test('saves an event whose title differs from the other provider’s event at the same venue and time', async () => {
    const { run, repository } = makeService([{}], [artWizardRecord()]);
    repository.findOtherProvidersEvents.mock.mockImplementation(() =>
      Promise.resolve([karabasEvent('Німецька органна музика')]),
    );

    const report = await run();

    assert.equal(report.created, 1);
    assert.equal(repository.createEvent.mock.callCount(), 1);
  });

  test('keeps updating the provider’s own saved event without looking for duplicates', async () => {
    const { run, repository } = makeService();
    repository.findEvent.mock.mockImplementation(() => Promise.resolve(theSavedEvent({ title: 'Old title' })));

    const report = await run();

    assert.equal(report.updated, 1);
    assert.equal(repository.findOtherProvidersEvents.mock.callCount(), 0);
  });
});
